Here is the commit message:
RDMA/siw: Fix QP destroy to wait for all references dropped.

Delay QP destroy completion until all siw references to QP are
dropped. The calling RDMA core will free QP structure after
successful return from siw_qp_destroy() call, so siw must not
hold any remaining reference to the QP upon return.
A use-after-free was encountered in xfstest generic/460, while
testing NFSoRDMA. Here, after a TCP connection drop by peer,
the triggered siw_cm_work_handler got delayed until after
QP destroy call, referencing a QP which has already freed.

Fixes: 303ae1cdfdf7 ("rdma/siw: application interface")
Reported-by: Olga Kornievskaia <kolga@netapp.com>
Signed-off-by: Bernard Metzler <bmt@zurich.ibm.com>
Link: https://lore.kernel.org/r/20220920082503.224189-1-bmt@zurich.ibm.com
Signed-off-by: Leon Romanovsky <leon@kernel.org>

Here is the root cause:
The bug was caused by a use-after-free condition where the `siw_cm_work_handler` was referencing a QP that had already been freed after a QP destroy call. This occurred because the QP destroy process did not wait for all references to the QP to be dropped before completing the destruction, leading to potential access of invalid memory.

Here is the patch:

 int siw_create_qp(struct ib_qp *ibqp, struct ib_qp_init_attr *attrs,
 		  struct ib_udata *udata)
 {
 	struct ib_pd *pd = ibqp->pd;
 	struct siw_qp *qp = to_siw_qp(ibqp);
 	struct ib_device *base_dev = pd->device;
 	struct siw_device *sdev = to_siw_dev(base_dev);
 	struct siw_ucontext *uctx =
 		rdma_udata_to_drv_context(udata, struct siw_ucontext,
 					  base_ucontext);
 	unsigned long flags;
 	int num_sqe, num_rqe, rv = 0;
 	size_t length;

 	siw_dbg(base_dev, "create new QP\n");

 	if (attrs->create_flags)
 		return -EOPNOTSUPP;

 	if (atomic_inc_return(&sdev->num_qp) > SIW_MAX_QP) {
 		siw_dbg(base_dev, "too many QP's\n");
 		rv = -ENOMEM;
 		goto err_atomic;
 	}
 	if (attrs->qp_type != IB_QPT_RC) {
 		siw_dbg(base_dev, "only RC QP's supported\n");
 		rv = -EOPNOTSUPP;
 		goto err_atomic;
 	}
 	if ((attrs->cap.max_send_wr > SIW_MAX_QP_WR) ||
 	    (attrs->cap.max_recv_wr > SIW_MAX_QP_WR) ||
 	    (attrs->cap.max_send_sge > SIW_MAX_SGE) ||
 	    (attrs->cap.max_recv_sge > SIW_MAX_SGE)) {
 		siw_dbg(base_dev, "QP size error\n");
 		rv = -EINVAL;
 		goto err_atomic;
 	}
 	if (attrs->cap.max_inline_data > SIW_MAX_INLINE) {
 		siw_dbg(base_dev, "max inline send: %d > %d\n",
 			attrs->cap.max_inline_data, (int)SIW_MAX_INLINE);
 		rv = -EINVAL;
 		goto err_atomic;
 	}
 	/*
 	 * NOTE: we allow for zero element SQ and RQ WQE's SGL's
 	 * but not for a QP unable to hold any WQE (SQ + RQ)
 	 */
 	if (attrs->cap.max_send_wr + attrs->cap.max_recv_wr == 0) {
 		siw_dbg(base_dev, "QP must have send or receive queue\n");
 		rv = -EINVAL;
 		goto err_atomic;
 	}

 	if (!attrs->send_cq || (!attrs->recv_cq && !attrs->srq)) {
 		siw_dbg(base_dev, "send CQ or receive CQ invalid\n");
 		rv = -EINVAL;
 		goto err_atomic;
 	}

 	init_rwsem(&qp->state_lock);
 	spin_lock_init(&qp->sq_lock);
 	spin_lock_init(&qp->rq_lock);
 	spin_lock_init(&qp->orq_lock);

 	rv = siw_qp_add(sdev, qp);
 	if (rv)
 		goto err_atomic;

 	num_sqe = attrs->cap.max_send_wr;
 	num_rqe = attrs->cap.max_recv_wr;

 	/* All queue indices are derived from modulo operations
 	 * on a free running 'get' (consumer) and 'put' (producer)
 	 * unsigned counter. Having queue sizes at power of two
 	 * avoids handling counter wrap around.
 	 */
 	if (num_sqe)
 		num_sqe = roundup_pow_of_two(num_sqe);
 	else {
 		/* Zero sized SQ is not supported */
 		rv = -EINVAL;
 		goto err_out_xa;
 	}
 	if (num_rqe)
 		num_rqe = roundup_pow_of_two(num_rqe);

 	if (udata)
 		qp->sendq = vmalloc_user(num_sqe * sizeof(struct siw_sqe));
 	else
 		qp->sendq = vzalloc(num_sqe * sizeof(struct siw_sqe));

 	if (qp->sendq == NULL) {
 		rv = -ENOMEM;
 		goto err_out_xa;
 	}
 	if (attrs->sq_sig_type != IB_SIGNAL_REQ_WR) {
 		if (attrs->sq_sig_type == IB_SIGNAL_ALL_WR)
 			qp->attrs.flags |= SIW_SIGNAL_ALL_WR;
 		else {
 			rv = -EINVAL;
 			goto err_out_xa;
 		}
 	}
 	qp->pd = pd;
 	qp->scq = to_siw_cq(attrs->send_cq);
 	qp->rcq = to_siw_cq(attrs->recv_cq);

 	if (attrs->srq) {
 		/*
 		 * SRQ support.
 		 * Verbs 6.3.7: ignore RQ size, if SRQ present
 		 * Verbs 6.3.5: do not check PD of SRQ against PD of QP
 		 */
 		qp->srq = to_siw_srq(attrs->srq);
 		qp->attrs.rq_size = 0;
 		siw_dbg(base_dev, "QP [%u]: SRQ attached\n",
 			qp->base_qp.qp_num);
 	} else if (num_rqe) {
 		if (udata)
 			qp->recvq =
 				vmalloc_user(num_rqe * sizeof(struct siw_rqe));
 		else
 			qp->recvq = vzalloc(num_rqe * sizeof(struct siw_rqe));

 		if (qp->recvq == NULL) {
 			rv = -ENOMEM;
 			goto err_out_xa;
 		}
 		qp->attrs.rq_size = num_rqe;
 	}
 	qp->attrs.sq_size = num_sqe;
 	qp->attrs.sq_max_sges = attrs->cap.max_send_sge;
 	qp->attrs.rq_max_sges = attrs->cap.max_recv_sge;

 	/* Make those two tunables fixed for now. */
 	qp->tx_ctx.gso_seg_limit = 1;
 	qp->tx_ctx.zcopy_tx = zcopy_tx;

 	qp->attrs.state = SIW_QP_STATE_IDLE;

 	if (udata) {
 		struct siw_uresp_create_qp uresp = {};

 		uresp.num_sqe = num_sqe;
 		uresp.num_rqe = num_rqe;
 		uresp.qp_id = qp_id(qp);

 		if (qp->sendq) {
 			length = num_sqe * sizeof(struct siw_sqe);
 			qp->sq_entry =
 				siw_mmap_entry_insert(uctx, qp->sendq,
 						      length, &uresp.sq_key);
 			if (!qp->sq_entry) {
 				rv = -ENOMEM;
 				goto err_out_xa;
 			}
 		}

 		if (qp->recvq) {
 			length = num_rqe * sizeof(struct siw_rqe);
 			qp->rq_entry =
 				siw_mmap_entry_insert(uctx, qp->recvq,
 						      length, &uresp.rq_key);
 			if (!qp->rq_entry) {
 				uresp.sq_key = SIW_INVAL_UOBJ_KEY;
 				rv = -ENOMEM;
 				goto err_out_xa;
 			}
 		}

 		if (udata->outlen < sizeof(uresp)) {
 			rv = -EINVAL;
 			goto err_out_xa;
 		}
 		rv = ib_copy_to_udata(udata, &uresp, sizeof(uresp));
 		if (rv)
 			goto err_out_xa;
 	}
 	qp->tx_cpu = siw_get_tx_cpu(sdev);
 	if (qp->tx_cpu < 0) {
 		rv = -EINVAL;
 		goto err_out_xa;
 	}
 	INIT_LIST_HEAD(&qp->devq);
 	spin_lock_irqsave(&sdev->lock, flags);
 	list_add_tail(&qp->devq, &sdev->qp_list);
 	spin_unlock_irqrestore(&sdev->lock, flags);

+	init_completion(&qp->qp_free);
+
 	return 0;

 err_out_xa:
 	xa_erase(&sdev->qp_xa, qp_id(qp));
 	if (uctx) {
 		rdma_user_mmap_entry_remove(qp->sq_entry);
 		rdma_user_mmap_entry_remove(qp->rq_entry);
 	}
 	vfree(qp->sendq);
 	vfree(qp->recvq);

 err_atomic:
 	atomic_dec(&sdev->num_qp);
 	return rv;
 }


 int siw_destroy_qp(struct ib_qp *base_qp, struct ib_udata *udata)
 {
 	struct siw_qp *qp = to_siw_qp(base_qp);
 	struct siw_ucontext *uctx =
 		rdma_udata_to_drv_context(udata, struct siw_ucontext,
 					  base_ucontext);
 	struct siw_qp_attrs qp_attrs;

 	siw_dbg_qp(qp, "state %d\n", qp->attrs.state);

 	/*
 	 * Mark QP as in process of destruction to prevent from
 	 * any async callbacks to RDMA core
 	 */
 	qp->attrs.flags |= SIW_QP_IN_DESTROY;
 	qp->rx_stream.rx_suspend = 1;

 	if (uctx) {
 		rdma_user_mmap_entry_remove(qp->sq_entry);
 		rdma_user_mmap_entry_remove(qp->rq_entry);
 	}

 	down_write(&qp->state_lock);

 	qp_attrs.state = SIW_QP_STATE_ERROR;
 	siw_qp_modify(qp, &qp_attrs, SIW_QP_ATTR_STATE);

 	if (qp->cep) {
 		siw_cep_put(qp->cep);
 		qp->cep = NULL;
 	}
 	up_write(&qp->state_lock);

 	kfree(qp->tx_ctx.mpa_crc_hd);
 	kfree(qp->rx_stream.mpa_crc_hd);

 	qp->scq = qp->rcq = NULL;

 	siw_qp_put(qp);
+	wait_for_completion(&qp->qp_free);

 	return 0;
 }



